#!/bin/bash

# Pre-deployment validation: Check required environment variables
if [ -f ".env.test" ]; then
    echo "Validating environment variables from .env.test...";

    # Read each line in .env.test
    while IFS= read -r line || [[ -n "$line" ]]; do
        # Skip comments and empty lines
        if [[ "$line" =~ ^#.*$ || -z "$line" ]]; then
            continue;
        fi

        # Extract the key (part before =)
        key="${line%%=*}";

        # Check if the key is set in the environment and not empty
        if [ -z "${!key}" ]; then
            echo "Error: Required environment variable $key is not set or is empty.";
            exit 1;
        fi
    done < ".env.test";

    echo "All required environment variables are set.";
else
    echo ".env.test not found. Skipping environment variable validation.";
fi

# Create the release archive
DIR_NAME=$(basename "$(pwd)")
TIMESTAMP=$(date +'%Y%m%d%H%M%S')
RELEASE_NAME="${DIR_NAME}-release-${TIMESTAMP}.tar.gz"

tar --exclude='./node_modules' --exclude='./.git' -czf "$RELEASE_NAME" .

echo "Release archive created: $RELEASE_NAME"
